INSERT INTO public.workflow_config
  (config_type, config_value, workflow_template_id, review_period, review_year, is_ongoing)
SELECT 'employee', p.id::text, t.id, NULL, NULL, false
FROM s
JOIN public.profiles p ON p.employee_code = s.employee_code
JOIN public.workflow_templates t ON t.display_name = s.template_display_name
ON CONFLICT (config_type, config_value) WHERE review_period IS NULL
DO UPDATE SET workflow_template_id = EXCLUDED.workflow_template_id, updated_at = now();

